1	// Acceptance test for the change request:
2	//   "Let me record what a client has paid on an invoice. Store the amount and the date. Show it on
3	//    the invoice."
4	//
5	// An invoice gains a record of what has been PAID against it. On the invoice's own detail page
6	// (invoice-detail-page, the child route /invoices/<id>) a payments region (invoice-payments) shows
7	// the payments taken against that invoice in a table (invoice-payments-table); each payment is its
8	// own row (payment-row-<id>) carrying the AMOUNT paid (payment-amount) and the DATE it was paid
9	// (payment-date). A payment is recorded with the payments form (payment-form): an amount and a date
10	// (payment-form-amount / payment-form-date, submitted with payment-form-submit). A recorded payment
11	// must be a real payment — a missing or non-positive amount is rejected with a visible error
12	// (payment-form-error) and nothing is recorded. A valid payment joins the list, shows its amount and
13	// date, is scoped to its own invoice, and survives a fresh load from the server.
14	//
15	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
16	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId },
17	// `invoices` honours { id, amount, projectId, status } and `payments` honours
18	// { id, invoiceId, amount, date }. This change surfaces no audit records, so there is nothing to
19	// assert on the audit channel.
20	import { test, expect, type Page, type Locator } from '@playwright/test';
21	import { resetAndSeed } from '../support/seed';
22	
23	const paymentRows = (page: Page) => page.locator('[data-testid^="payment-row-"]');
24	
25	// A seeded payment is addressed by its fixture id; a freshly recorded one gets a server-assigned id,
26	// so it is located instead by the AMOUNT it carries (amounts in each test are chosen distinct and
27	// none a substring of another). Mirrors how invoice-lineitems.spec.ts finds a freshly added row.
28	const rowById = (page: Page, id: number): Locator => page.getByTestId(`payment-row-${id}`);
29	const rowByAmount = (page: Page, amount: number): Locator =>
30	  paymentRows(page).filter({ has: page.getByTestId('payment-amount').getByText(String(amount)) });
31	
32	// The request names no date format, so a date assertion binds to WHICH date a cell shows rather than
33	// to one presentation (ISO 2021-03-14, US 3/14/2021, or long "March 14, 2021"): in every common
34	// rendering the four-digit year and the day-of-month both appear. Dates in each test are chosen with
35	// DISTINCT years and distinct day numbers, so requiring a cell to carry its own year and day — and
36	// NOT any other seeded year — pins it to exactly one date. Mirrors invoice-dates.spec.ts.
37	type D = { iso: string; year: string; day: string };
38	const d = (iso: string): D => {
39	  const [year, , day] = iso.split('-');
40	  return { iso, year, day: String(Number(day)) };
41	};
42	
43	// A payment amount may be rendered as money ($60.00) or bare (60); assert the figure is PRESENT so
44	// the test binds to the value, not one presentation.
45	async function expectAmount(cell: Locator, amount: number): Promise<void> {
46	  await expect(cell).toContainText(String(amount));
47	}
48	
49	async function expectDate(cell: Locator, want: D, others: D[]): Promise<void> {
50	  await expect(cell).toContainText(want.year);
51	  await expect(cell).toContainText(want.day);
52	  for (const other of others) {
53	    if (other.year !== want.year) {
54	      await expect(cell).not.toContainText(other.year);
55	    }
56	  }
57	}
58	
59	async function gotoInvoice(page: Page, id: number): Promise<void> {
60	  await page.goto(`/invoices/${id}`);
61	  await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
62	}
63	
64	test.describe('An invoice shows what has been paid against it', () => {
65	  test('the detail page shows each seeded payment with its amount and date', async ({ page }) => {
66	    const first = d('2021-03-14');
67	    const second = d('2022-08-19');
68	
69	    await resetAndSeed({
70	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
71	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
72	      invoices: [{ id: 1, amount: 500, projectId: 1, status: 'SENT' }],
73	      payments: [
74	        { id: 1, invoiceId: 1, amount: 60, date: first.iso },
75	        { id: 2, invoiceId: 1, amount: 175, date: second.iso },
76	      ],
77	    });
78	
79	    await gotoInvoice(page, 1);
80	
81	    // The payments are shown on the invoice, in their own region and table.
82	    await expect(page.getByTestId('invoice-payments')).toBeVisible();
83	    await expect(page.getByTestId('invoice-payments-table')).toBeVisible();
84	    await expect(paymentRows(page)).toHaveCount(2);
85	
86	    // Each payment shows its own amount and its own date.
87	    await expectAmount(rowById(page, 1).getByTestId('payment-amount'), 60);
88	    await expectDate(rowById(page, 1).getByTestId('payment-date'), first, [second]);
89	
90	    await expectAmount(rowById(page, 2).getByTestId('payment-amount'), 175);
91	    await expectDate(rowById(page, 2).getByTestId('payment-date'), second, [first]);
92	  });
93	
94	  test('an invoice with no payments shows the region but no payment rows', async ({ page }) => {
95	    await resetAndSeed({
96	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
97	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
98	      invoices: [{ id: 1, amount: 500, projectId: 1, status: 'SENT' }],
99	      payments: [],
100	    });
101	
102	    await gotoInvoice(page, 1);
103	
104	    // Nothing paid yet: the region is still there, ready to record a payment, but shows no rows.
105	    await expect(page.getByTestId('invoice-payments')).toBeVisible();
106	    await expect(paymentRows(page)).toHaveCount(0);
107	  });
108	
109	  test("payments are scoped to their own invoice", async ({ page }) => {
110	    const onOne = d('2021-03-14');
111	    const onTwo = d('2022-08-19');
112	
113	    await resetAndSeed({
114	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
115	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
116	      invoices: [
117	        { id: 1, amount: 500, projectId: 1, status: 'SENT' },
118	        { id: 2, amount: 800, projectId: 1, status: 'SENT' },
119	      ],
120	      payments: [
121	        { id: 1, invoiceId: 1, amount: 60, date: onOne.iso },
122	        { id: 2, invoiceId: 2, amount: 175, date: onTwo.iso },
123	      ],
124	    });
125	
126	    // Invoice 1's detail shows only invoice 1's payment, not invoice 2's.
127	    await gotoInvoice(page, 1);
128	    await expect(paymentRows(page)).toHaveCount(1);
129	    await expect(rowById(page, 1)).toBeVisible();
130	    await expect(rowById(page, 2)).toHaveCount(0);
131	    await expectAmount(rowById(page, 1).getByTestId('payment-amount'), 60);
132	
133	    // Invoice 2's detail shows only invoice 2's payment.
134	    await gotoInvoice(page, 2);
135	    await expect(paymentRows(page)).toHaveCount(1);
136	    await expect(rowById(page, 2)).toBeVisible();
137	    await expect(rowById(page, 1)).toHaveCount(0);
138	    await expectAmount(rowById(page, 2).getByTestId('payment-amount'), 175);
139	  });
140	});
141	
142	test.describe('Recording a payment on an invoice', () => {
143	  test('recording a payment shows its amount and date, and it survives a fresh load', async ({
144	    page,
145	  }) => {
146	    const when = d('2023-05-27');
147	
148	    await resetAndSeed({
149	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
150	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
151	      invoices: [{ id: 1, amount: 500, projectId: 1, status: 'SENT' }],
152	      payments: [],
153	    });
154	
155	    await gotoInvoice(page, 1);
156	    await expect(paymentRows(page)).toHaveCount(0);
157	
158	    // Record what the client paid: an amount and the date it was paid.
159	    await expect(page.getByTestId('payment-form')).toBeVisible();
160	    await page.getByTestId('payment-form-amount').fill('250');
161	    await page.getByTestId('payment-form-date').fill(when.iso);
162	    await page.getByTestId('payment-form-submit').click();
163	
164	    // It joins the list, showing the amount paid and the date.
165	    const added = rowByAmount(page, 250);
166	    await expect(added).toHaveCount(1);
167	    await expectAmount(added.getByTestId('payment-amount'), 250);
168	    await expectDate(added.getByTestId('payment-date'), when, []);
169	    await expect(paymentRows(page)).toHaveCount(1);
170	
171	    // The payment is held by the server: it survives a fresh load.
172	    await page.reload();
173	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
174	    await expect(paymentRows(page)).toHaveCount(1);
175	    const reloaded = rowByAmount(page, 250);
176	    await expectAmount(reloaded.getByTestId('payment-amount'), 250);
177	    await expectDate(reloaded.getByTestId('payment-date'), when, []);
178	  });
179	
180	  test('recording a payment adds to those already on the invoice', async ({ page }) => {
181	    const seeded = d('2021-03-14');
182	    const added = d('2023-05-27');
183	
184	    await resetAndSeed({
185	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
186	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
187	      invoices: [{ id: 1, amount: 500, projectId: 1, status: 'SENT' }],
188	      payments: [{ id: 1, invoiceId: 1, amount: 60, date: seeded.iso }],
189	    });
190	
191	    await gotoInvoice(page, 1);
192	    await expect(paymentRows(page)).toHaveCount(1);
193	
194	    await page.getByTestId('payment-form-amount').fill('250');
195	    await page.getByTestId('payment-form-date').fill(added.iso);
196	    await page.getByTestId('payment-form-submit').click();
197	
198	    // Both payments are now shown — the new one did not replace the seeded one.
199	    await expect(paymentRows(page)).toHaveCount(2);
200	    await expectAmount(rowById(page, 1).getByTestId('payment-amount'), 60);
201	    await expectDate(rowById(page, 1).getByTestId('payment-date'), seeded, [added]);
202	
203	    const newRow = rowByAmount(page, 250);
204	    await expect(newRow).toHaveCount(1);
205	    await expectDate(newRow.getByTestId('payment-date'), added, [seeded]);
206	  });
207	});
208	
209	test.describe('A recorded payment must be a real payment', () => {
210	  const seedNoPayments = () =>
211	    resetAndSeed({
212	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
213	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
214	      invoices: [{ id: 1, amount: 500, projectId: 1, status: 'SENT' }],
215	      payments: [],
216	    });
217	
218	  test('an empty submission is rejected and records nothing', async ({ page }) => {
219	    await seedNoPayments();
220	
221	    await gotoInvoice(page, 1);
